        try:
            self.headers["Host"]="crt.sh"
            resp = self.session.get(self.queryurl, headers=self.headers, timeout=self.timeout)
        except Exception as e:
            print('[CrtSearch] ERROR {e}'.format(e=str(e)))
            resp = None

        if resp is None:
            return []

        if resp.status_code == 403:
            return []

        return resp

