def clean_domains(domain):
    validator = re.compile("^(http|https)?[a-zA-Z0-9]+([\-\.]{1}[a-zA-Z0-9]+)*\.[a-zA-Z]{2,}$")
    domain_list = []

    for d in domain:
        match = validator.match(d)

        if(match):
            domain_list.append(match.string)
    return domain_list

