import base64, requests, dns.message, dns.name, dns.rdatatype, dns.dnssec, dns.flags, dns.rcode, dns.rrset

def q(name, rdtype):
    msg=dns.message.make_query(name,rdtype,want_dnssec=True)
    data=msg.to_wire()
    r=requests.post('https://cloudflare-dns.com/dns-query', params={'dns':base64.urlsafe_b64encode(data).rstrip(b'=').decode()}, headers={'accept':'application/dns-message'}, timeout=10)
    print(name,rdtype,r.status_code,len(r.content))
    r.raise_for_status()
    return dns.message.from_wire(r.content)

def rrset_from(resp,name,rdtype):
    name=dns.name.from_text(name)
    for rr in resp.answer:
        if rr.name==name and rr.rdtype==rdtype and rr.rdclass==1:
            return rr
    return None

def sig_for(resp,name,rdtype):
    name=dns.name.from_text(name)
    for rr in resp.answer:
        if rr.name==name and rr.rdtype==dns.rdatatype.RRSIG and rr.rdclass==1:
            # covers
            if rr.covers()==rdtype:
                return rr
    return None

# root anchors
anchors=[dns.dnssec.make_ds('.', dns.rdata.from_text(1,257,'.'), 8, 'E06D44B80B8F1D39A95C0B0D7C65D08458E880409BBC683457104237C7F8EC8D')]
# Actually make DS from DNSKEY
r=q('.','DNSKEY')
keyset=rrset_from(r,'.',dns.rdatatype.DNSKEY)
sigs=sig_for(r,'.',dns.rdatatype.DNSKEY)
print('root keyset',keyset,'sigs',sigs)
for rdata in keyset:
    tag=dns.dnssec.key_id(rdata)
    print('key',tag,rdata.algorithm,rdata.flags)
    for an in ['E06D44B80B8F1D39A95C0B0D7C65D08458E880409BBC683457104237C7F8EC8D','683D2D0ACB8C9B712A1948B27F741219298D0A450D612C483AF444A4C0FB2B16']:
        ds=dns.dnssec.make_ds('.',rdata,8,an)
        print(' ds',ds)
# validation root keyset with keys mapping all DNSKEYs
try:
    dns.dnssec.validate(keyset,sigs,{dns.name.root:keyset})
    print('ROOT VALID')
except Exception as e:
    print('root invalid',repr(e))
