def _call_compatible(func, *args, **kwargs):
    try:
       signature=inspect.signature(func)
    except (TypeError,ValueError): return func(*args, **kwargs)
    params=signature.parameters
    if any(p.kind == VAR_KEYWORD): return func(*args,**kwargs)
    filtered={k:v for k,v in kwargs.items() if k in params}
    return func(*args,**filtered)
```
